namespace IngSoft.Api.Entities;

public class Usuario { public int IdUsuario { get; set; } public string Nombre { get; set; } = string.Empty; public string Correo { get; set; } = string.Empty; public string Contrasena { get; set; } = string.Empty; }
public class Cliente { public int IdCliente { get; set; } public string RazonSocial { get; set; } = string.Empty; public string Cuit { get; set; } = string.Empty; public string TipoCliente { get; set; } = string.Empty; public string EstadoCredito { get; set; } = string.Empty; public ICollection<Pedido> Pedidos { get; set; } = []; }
public class Producto { public int IdProducto { get; set; } public string Descripcion { get; set; } = string.Empty; public decimal PrecioMinorista { get; set; } public int StockActual { get; set; } public int StockMinimo { get; set; } public ICollection<DetalleItem> Detalles { get; set; } = []; }
public class Pedido { public int IdPedido { get; set; } public int IdCliente { get; set; } public DateTime FechaIngreso { get; set; } public string Estado { get; set; } = string.Empty; public Cliente Cliente { get; set; } = null!; public ICollection<DetalleItem> Detalles { get; set; } = []; public ICollection<Cotizacion> Cotizaciones { get; set; } = []; }
public class DetalleItem { public int IdDetalle { get; set; } public int IdPedido { get; set; } public int IdProducto { get; set; } public int Cantidad { get; set; } public decimal PrecioUnitario { get; set; } public Pedido Pedido { get; set; } = null!; public Producto Producto { get; set; } = null!; }
public class Cotizacion { public int IdCotizacion { get; set; } public int IdPedido { get; set; } public DateTime FechaEmision { get; set; } public decimal MontoTotal { get; set; } public string Estado { get; set; } = string.Empty; public Pedido Pedido { get; set; } = null!; public ICollection<OrdenCompra> OrdenesCompra { get; set; } = []; }
public class OrdenCompra { public int IdOc { get; set; } public int IdCotizacion { get; set; } public string NroOcCliente { get; set; } = string.Empty; public DateTime FechaRecepcion { get; set; } public string Estado { get; set; } = string.Empty; public string Pago { get; set; } = string.Empty; public Cotizacion Cotizacion { get; set; } = null!; public Cobro? Cobro { get; set; } public ICollection<Remito> Remitos { get; set; } = []; }
public class Cobro { public int IdCobro { get; set; } public int IdOc { get; set; } public DateTime FechaRegistro { get; set; } public string MedioPago { get; set; } = string.Empty; public string? Comprobante { get; set; } public string Estado { get; set; } = string.Empty; public OrdenCompra OrdenCompra { get; set; } = null!; }
public class Remito { public int IdRemito { get; set; } public int IdOc { get; set; } public DateTime FechaEmision { get; set; } public string EstadoEntrega { get; set; } = string.Empty; public byte[]? FirmaDigitalCliente { get; set; } public OrdenCompra OrdenCompra { get; set; } = null!; public ICollection<Factura> Facturas { get; set; } = []; }
public class Factura { public int IdFactura { get; set; } public int IdRemito { get; set; } public string NroFactura { get; set; } = string.Empty; public DateTime FechaEmision { get; set; } public string Cae { get; set; } = string.Empty; public decimal MontoTotal { get; set; } public Remito Remito { get; set; } = null!; }
